  void baseline(){audit.acceptBaseline();check("Accepting reviewed environment clears change notice",!audit.hasChanges());session.prefs.edit().putInt("privacyLevel",2).commit();session.privacy.apply();audit.refresh(true);check("Protection change is detected without clearing login",audit.hasChanges()&&mainUrl.equals(remote.getUrl()));audit.acceptBaseline();check("Updated baseline persists per environment",!new EnvironmentAudit(session).hasChanges());session.prefs.edit().putInt("privacyLevel",1).commit();session.privacy.apply();audit.acceptBaseline();
    int requests=audit.publicRequests;session.guard.setBlocked(true);session.networkReady=false;check("Network audit refuses an unprotected connection",!audit.start(true,()->{}));check("Refused audit has no test requests",audit.publicRequests==requests);session.networkReady=true;session.guard.setBlocked(false);stale();}
