  void waitNative(long previous){if(!audit.nativeStarted&&attempts++<40){handler.postDelayed(()->waitNative(previous),50);return;}check("Cancellation fixture reaches a real native request",audit.nativeStarted);audit.cancel();check("Cancel destroys only the diagnostic WebView",!audit.running&&audit.diagnostic==null&&mainUrl.equals(remote.getUrl()));handler.postDelayed(()->{check("Cancel closes the native socket without queued waits",audit.disconnected);check("Cancelled job does not overwrite prior report",audit.report.optLong("at")==previous);check("Brief copy contains no raw IP or credentials",!audit.safeCopy().contains("203.0.113.8")&&!audit.safeCopy().contains("audit_cookie_must_not_leave"));write();},400);}
